require_once '../config/db.php'; require_once '../includes/seguridad.php'; require_once '../includes/permisos_documentos.php';
try{seguridad_exigir_sesion($pdo,true,false,true);$u=(int)($_SESSION['id_usuario']??0);$e=(int)($_SESSION['id_empresa']??0);exigir_permiso_accion($pdo,$u,$e,'oracle_pagos');$tipo=strtoupper(trim((string)($_POST['tipo_documento']??'')));$id=(int)($_POST['id_documento']??0);if(!in_array($tipo,['FACTURA','EXP_DETALLE'],true)||$id<=0)throw new RuntimeException('Documento no válido.');$pdo->prepare("DELETE FROM oracle_conciliacion_clasificaciones WHERE id_empresa=? AND tipo_documento=? AND id_documento_origen=?")->execute([$e,$tipo,$id]);$tabla=$tipo==='FACTURA'?'oracle_facturas':'oracle_gastos';$pdo->prepare("UPDATE {$tabla} SET conciliado=0,estatus_conciliacion='PENDIENTE',fecha_conciliacion=NULL WHERE id=? AND id_empresa=?")->execute([$id,$e]);echo json_encode(['success'=>true]);}catch(Throwable $x){http_response_code(400);echo json_encode(['success'=>false,'error'=>$x->getMessage()]);}
